def xml_escape_attrs(d):
    esc = {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;'}
    parts = []
    for k, v in d.items():
        if v is None:
            continue
        parts.append(str(k) + '="' + ''.join(esc.get(c, c) for c in str(v)) + '"')
    return ' '.join(parts)

